-- Conferência rápida
SELECT 'contas demo' AS item, COUNT(*) AS total FROM tb_conta WHERE email_conta LIKE '%@demo.xepamais.com.br'
UNION ALL SELECT 'xepas à venda hoje', COUNT(*) FROM tb_xepa WHERE status_xepa = 'DISPONIVEL' AND data_retirada >= CURDATE()
